import { DateTime } from 'luxon';
import type { TimezoneInfo } from '@/types/timezone.types';

// Localized names and readings, generated by scripts/generate-timezones.mjs.
type StaticTimezone = Omit<TimezoneInfo, 'offset' | 'offsetMinutes'>;

const POPULAR_TIMEZONES = [
  'Asia/Tokyo',
  'America/New_York',
  'America/Los_Angeles',
  'Europe/London',
  'Europe/Paris',
  'Asia/Singapore',
  'Asia/Shanghai',
  'Australia/Sydney',
  'Asia/Dubai',
  'America/Chicago',
];

// The JSON is loaded lazily so it gets its own cacheable chunk instead of growing the page bundle.
async function loadStaticTimezones(): Promise<StaticTimezone[]> {
  const data = await import('@/data/timezones.json');
  return data.default as unknown as StaticTimezone[];
}

// Converts a UTC offset in minutes to a formatted string (e.g. 540 → "+09:00", -300 → "-05:00").
function formatOffset(minutes: number): string {
  const sign = minutes >= 0 ? '+' : '-';
  const abs = Math.abs(minutes);
  const hours = Math.floor(abs / 60);
  const mins = abs % 60;
  return `${sign}${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
}

// The offset is calculated at call time so DST (Daylight Saving Time) changes are reflected correctly.
// Zones the browser does not recognize are dropped.
function withCurrentOffsets(timezones: StaticTimezone[]): TimezoneInfo[] {
  const now = DateTime.now();
  return timezones
    .flatMap((tz) => {
      const local = now.setZone(tz.identifier);
      if (!local.isValid) return [];
      return [{ ...tz, offset: formatOffset(local.offset), offsetMinutes: local.offset }];
    })
    .sort((a, b) => a.offsetMinutes - b.offsetMinutes); // Sorted west to east (e.g. -12:00 → +14:00)
}

export const timezoneService = {
  async getAll(): Promise<TimezoneInfo[]> {
    return withCurrentOffsets(await loadStaticTimezones());
  },

  async getPopular(): Promise<TimezoneInfo[]> {
    const all = await loadStaticTimezones();
    const popular = all.filter((tz) => POPULAR_TIMEZONES.includes(tz.identifier));
    return withCurrentOffsets(popular);
  },
};
